-- Immutable Operational Closeout and Mission Completion evidence.
do $migration$ begin if to_regclass('storage.buckets')is not null then execute $storage$insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types)values('mission-operational-evidence','mission-operational-evidence',false,3145728,array['application/vnd.google-earth.kml+xml','text/plain','text/csv','application/octet-stream'])on conflict(id)do update set public=false,file_size_limit=excluded.file_size_limit,allowed_mime_types=excluded.allowed_mime_types$storage$;end if;end$migration$;
create table public.mission_operational_imports(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null,operating_location_id uuid not null,mission_id uuid not null,version_number integer not null check(version_number>0),
 internal_file_id uuid not null default gen_random_uuid(),storage_provider text not null,storage_bucket text not null,storage_object_key text not null,original_filename text not null,source_format text not null,content_type text not null,file_size_bytes bigint not null check(file_size_bytes>=0),sha256_checksum text not null,
 evidence_type text not null check(evidence_type in('FINAL_KML','FLIGHT_LINES','TELEMETRY','FLIGHT_LOG')),parse_status text not null check(parse_status in('PARSED','RETAINED','REJECTED')),validation_result jsonb not null default'{}',derived_statistics jsonb not null default'{}',operational_geometry jsonb,source_metadata jsonb not null default'{}',imported_by_internal_user_id uuid not null,imported_at timestamptz not null default now(),
 unique(organisation_id,id),unique(organisation_id,mission_id,version_number),unique(organisation_id,internal_file_id),foreign key(organisation_id,mission_id)references public.missions(organisation_id,id),foreign key(organisation_id,operating_location_id)references public.operating_locations(organisation_id,id),foreign key(organisation_id,imported_by_internal_user_id)references public.internal_users(organisation_id,id)
);
create table public.mission_operational_resource_revisions(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null,operating_location_id uuid not null,mission_id uuid not null,version_number integer not null check(version_number>0),actual_resources jsonb not null check(jsonb_typeof(actual_resources)='object'),planned_resources_snapshot jsonb not null default'{}',recorded_by_internal_user_id uuid not null,recorded_at timestamptz not null default now(),unique(organisation_id,id),unique(organisation_id,mission_id,version_number),foreign key(organisation_id,mission_id)references public.missions(organisation_id,id),foreign key(organisation_id,operating_location_id)references public.operating_locations(organisation_id,id),foreign key(organisation_id,recorded_by_internal_user_id)references public.internal_users(organisation_id,id)
);
create table public.mission_operational_chemical_revisions(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null,operating_location_id uuid not null,mission_id uuid not null,version_number integer not null check(version_number>0),changed_from_plan boolean not null,actual_usage jsonb not null check(jsonb_typeof(actual_usage)='object'),planned_chemicals_snapshot jsonb not null default'{}',recorded_by_internal_user_id uuid not null,recorded_at timestamptz not null default now(),unique(organisation_id,id),unique(organisation_id,mission_id,version_number),foreign key(organisation_id,mission_id)references public.missions(organisation_id,id),foreign key(organisation_id,operating_location_id)references public.operating_locations(organisation_id,id),foreign key(organisation_id,recorded_by_internal_user_id)references public.internal_users(organisation_id,id)
);
create table public.mission_operational_events(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null,operating_location_id uuid not null,mission_id uuid not null,batch_version integer not null check(batch_version>0),event_index integer not null check(event_index>=0),event_type text not null,event_details jsonb not null default'{}',occurred_at timestamptz,no_events_declaration boolean not null default false,recorded_by_internal_user_id uuid not null,recorded_at timestamptz not null default now(),unique(organisation_id,id),unique(organisation_id,mission_id,batch_version,event_index),foreign key(organisation_id,mission_id)references public.missions(organisation_id,id),foreign key(organisation_id,operating_location_id)references public.operating_locations(organisation_id,id),foreign key(organisation_id,recorded_by_internal_user_id)references public.internal_users(organisation_id,id),check((no_events_declaration and event_type='NO_OPERATIONAL_EVENTS')or(not no_events_declaration and event_type<>'NO_OPERATIONAL_EVENTS'))
);
create table public.mission_operational_revisions(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null,operating_location_id uuid not null,mission_id uuid not null,version_number integer not null check(version_number>0),authorisation_revision_id uuid not null,source_file_ids uuid[] not null default'{}',resource_revision_id uuid not null,chemical_revision_id uuid not null,event_ids uuid[] not null default'{}',review_snapshot jsonb not null check(jsonb_typeof(review_snapshot)='object'),operator_notes text,submitted_by_internal_user_id uuid not null,submitted_at timestamptz not null default now(),unique(organisation_id,id),unique(organisation_id,mission_id,version_number),foreign key(organisation_id,mission_id)references public.missions(organisation_id,id),foreign key(organisation_id,operating_location_id)references public.operating_locations(organisation_id,id),foreign key(organisation_id,authorisation_revision_id)references public.mission_authorisation_revisions(organisation_id,id),foreign key(organisation_id,resource_revision_id)references public.mission_operational_resource_revisions(organisation_id,id),foreign key(organisation_id,chemical_revision_id)references public.mission_operational_chemical_revisions(organisation_id,id),foreign key(organisation_id,submitted_by_internal_user_id)references public.internal_users(organisation_id,id)
);
create table public.mission_completion_revisions(
 id uuid primary key default gen_random_uuid(),organisation_id uuid not null,operating_location_id uuid not null,mission_id uuid not null,version_number integer not null check(version_number>0),authorisation_revision_id uuid not null,operational_revision_id uuid not null,completion_snapshot jsonb not null check(jsonb_typeof(completion_snapshot)='object'),declaration text not null,flight_lines_override boolean not null default false,override_reason text,override_personnel_id uuid,completed_by_internal_user_id uuid not null,completed_at timestamptz not null default now(),unique(organisation_id,id),unique(organisation_id,mission_id,version_number),foreign key(organisation_id,mission_id)references public.missions(organisation_id,id),foreign key(organisation_id,operating_location_id)references public.operating_locations(organisation_id,id),foreign key(organisation_id,authorisation_revision_id)references public.mission_authorisation_revisions(organisation_id,id),foreign key(organisation_id,operational_revision_id)references public.mission_operational_revisions(organisation_id,id),foreign key(organisation_id,override_personnel_id)references public.personnel(organisation_id,id),foreign key(organisation_id,completed_by_internal_user_id)references public.internal_users(organisation_id,id),check(not flight_lines_override or(length(trim(coalesce(override_reason,'')))>0 and override_personnel_id is not null))
);

do $$declare t text;begin foreach t in array array['mission_operational_imports','mission_operational_resource_revisions','mission_operational_chemical_revisions','mission_operational_events','mission_operational_revisions','mission_completion_revisions']loop execute format('create index %I on public.%I(organisation_id,mission_id)',t||'_mission_idx',t);execute format('alter table public.%I enable row level security',t);execute format('alter table public.%I force row level security',t);execute format('create policy %I on public.%I for select to authenticated using(public.current_user_has_organisation_access(organisation_id))',t||'_tenant_read',t);execute format('create trigger %I before update or delete on public.%I for each row execute function public.reject_append_only_mutation()',t||'_immutable',t);execute format('revoke all on table public.%I from public,anon,authenticated',t);execute format('grant select,insert on table public.%I to service_role',t);end loop;end$$;

insert into public.permissions(organisation_id,code,description)select o.id,v.code,v.description from public.organisations o cross join(values('mission.operational.read','View Mission Operational Evidence'),('mission.operational.write','Record immutable Mission Operational Evidence'),('mission.completion.complete','Complete a Mission from selected evidence'),('mission.completion.override_flight_lines','Complete a Mission without flight-line evidence using an authorised exception'))v(code,description)on conflict(organisation_id,code)do update set description=excluded.description;
insert into public.role_permissions(organisation_id,role_id,permission_id)select r.organisation_id,r.id,p.id from public.roles r join public.permissions p on p.organisation_id=r.organisation_id where r.code='admin'and p.code in('mission.operational.read','mission.operational.write','mission.completion.complete','mission.completion.override_flight_lines')on conflict do nothing;
create function public.ftf_provision_operational_closeout_permissions()returns trigger language plpgsql security definer set search_path=public,pg_temp as $$begin insert into public.permissions(organisation_id,code,description)select new.organisation_id,v.code,v.description from(values('mission.operational.read','View Mission Operational Evidence'),('mission.operational.write','Record immutable Mission Operational Evidence'),('mission.completion.complete','Complete a Mission from selected evidence'),('mission.completion.override_flight_lines','Complete a Mission without flight-line evidence using an authorised exception'))v(code,description)on conflict(organisation_id,code)do nothing;if new.code='admin'then insert into public.role_permissions(organisation_id,role_id,permission_id)select new.organisation_id,new.id,p.id from public.permissions p where p.organisation_id=new.organisation_id and p.code in('mission.operational.read','mission.operational.write','mission.completion.complete','mission.completion.override_flight_lines')on conflict do nothing;end if;return new;end$$;
create trigger provision_operational_closeout_permissions after insert on public.roles for each row execute function public.ftf_provision_operational_closeout_permissions();

create function public.ftf_operational_location_allowed(p_organisation_id uuid,p_actor_internal_user_id uuid,p_location_id uuid)returns boolean language sql security definer set search_path=public,pg_temp stable as $$select exists(select 1 from public.memberships m join public.membership_operating_location_assignments a on a.organisation_id=m.organisation_id and a.membership_id=m.id where m.organisation_id=p_organisation_id and m.internal_user_id=p_actor_internal_user_id and m.is_active and m.archived_at is null and a.operating_location_id=p_location_id and a.is_active and a.archived_at is null)$$;

create function public.ftf_read_mission_operational_closeout(p_organisation_id uuid,p_mission_id uuid)returns jsonb language sql security definer set search_path=public,pg_temp as $$select case when m.id is null then null else jsonb_build_object('mission',to_jsonb(m)-'organisation_id','authorisation',(select to_jsonb(a)from public.mission_authorisation_revisions a where a.organisation_id=m.organisation_id and a.mission_id=m.id order by a.version_number desc limit 1),'availableResources',jsonb_build_object('aircraft',coalesce((select jsonb_agg(jsonb_build_object('id',a.id,'label',a.registration||' · '||a.model)order by a.registration)from public.aircraft a where a.organisation_id=m.organisation_id and a.operating_location_id=m.operating_location_id and a.archived_at is null),'[]'),'equipmentKits',coalesce((select jsonb_agg(jsonb_build_object('id',k.id,'label',k.name)order by k.name)from public.equipment_kits k where k.organisation_id=m.organisation_id and k.operating_location_id=m.operating_location_id and k.archived_at is null),'[]'),'personnel',coalesce((select jsonb_agg(jsonb_build_object('id',p.id,'label',p.full_name)order by p.full_name)from public.personnel p join public.personnel_operating_locations x on x.organisation_id=p.organisation_id and x.personnel_id=p.id where p.organisation_id=m.organisation_id and x.operating_location_id=m.operating_location_id and p.archived_at is null),'[]')),'imports',coalesce((select jsonb_agg(to_jsonb(i)order by i.version_number)from public.mission_operational_imports i where i.organisation_id=m.organisation_id and i.mission_id=m.id),'[]'),'resources',(select to_jsonb(r)from public.mission_operational_resource_revisions r where r.organisation_id=m.organisation_id and r.mission_id=m.id order by r.version_number desc limit 1),'chemicals',(select to_jsonb(c)from public.mission_operational_chemical_revisions c where c.organisation_id=m.organisation_id and c.mission_id=m.id order by c.version_number desc limit 1),'events',coalesce((select jsonb_agg(to_jsonb(e)order by e.batch_version,e.event_index)from public.mission_operational_events e where e.organisation_id=m.organisation_id and e.mission_id=m.id),'[]'),'operationalRevision',(select to_jsonb(o)from public.mission_operational_revisions o where o.organisation_id=m.organisation_id and o.mission_id=m.id order by o.version_number desc limit 1),'completion',(select to_jsonb(c)from public.mission_completion_revisions c where c.organisation_id=m.organisation_id and c.mission_id=m.id order by c.version_number desc limit 1))end from public.missions m where m.organisation_id=p_organisation_id and m.id=p_mission_id and m.archived_at is null$$;

create function public.ftf_create_mission_operational_import(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_expected_version integer,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare m public.missions%rowtype;current integer;r public.mission_operational_imports%rowtype;begin select*into m from public.missions where organisation_id=p_organisation_id and id=p_mission_id and archived_at is null for update;if not found then return jsonb_build_object('not_found',true);end if;if not public.ftf_operational_location_allowed(p_organisation_id,p_actor_internal_user_id,m.operating_location_id)then return jsonb_build_object('location_forbidden',true);end if;select coalesce(max(version_number),0)into current from public.mission_operational_imports where organisation_id=p_organisation_id and mission_id=p_mission_id;if current<>p_expected_version then return jsonb_build_object('conflict',true,'current_version',current);end if;insert into public.mission_operational_imports(organisation_id,operating_location_id,mission_id,version_number,storage_provider,storage_bucket,storage_object_key,original_filename,source_format,content_type,file_size_bytes,sha256_checksum,evidence_type,parse_status,validation_result,derived_statistics,operational_geometry,source_metadata,imported_by_internal_user_id)values(p_organisation_id,m.operating_location_id,p_mission_id,current+1,p_payload->>'storageProvider',p_payload->>'storageBucket',p_payload->>'storageObjectKey',p_payload->>'originalFilename',upper(p_payload->>'sourceFormat'),p_payload->>'contentType',(p_payload->>'fileSizeBytes')::bigint,p_payload->>'checksum',upper(p_payload->>'evidenceType'),upper(p_payload->>'parseStatus'),coalesce(p_payload->'validationResult','{}'),coalesce(p_payload->'derivedStatistics','{}'),p_payload->'operationalGeometry',coalesce(p_payload->'sourceMetadata','{}'),p_actor_internal_user_id)returning*into r;insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'mission.operational_import_created','mission',p_mission_id,jsonb_build_object('import_id',r.id,'version',r.version_number,'checksum',r.sha256_checksum));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'operational.mission.file_imported','mission',p_mission_id,jsonb_build_object('import_id',r.id,'version',r.version_number,'evidence_type',r.evidence_type));return jsonb_build_object('record',to_jsonb(r));end$$;

create function public.ftf_save_mission_actual_resources(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_expected_version integer,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare m public.missions%rowtype;current integer;r public.mission_operational_resource_revisions%rowtype;a jsonb;begin select*into m from public.missions where organisation_id=p_organisation_id and id=p_mission_id and archived_at is null for update;if not found then return jsonb_build_object('not_found',true);end if;if not public.ftf_operational_location_allowed(p_organisation_id,p_actor_internal_user_id,m.operating_location_id)then return jsonb_build_object('location_forbidden',true);end if;select coalesce(max(version_number),0)into current from public.mission_operational_resource_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id;if current<>p_expected_version then return jsonb_build_object('conflict',true,'current_version',current);end if;select evidence_manifest#>'{planning}'into a from public.mission_authorisation_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id order by version_number desc limit 1;if a is null then return jsonb_build_object('not_authorised',true);end if;insert into public.mission_operational_resource_revisions(organisation_id,operating_location_id,mission_id,version_number,actual_resources,planned_resources_snapshot,recorded_by_internal_user_id)values(p_organisation_id,m.operating_location_id,p_mission_id,current+1,p_payload,a,p_actor_internal_user_id)returning*into r;insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'mission.actual_resources_saved','mission',p_mission_id,jsonb_build_object('revision_id',r.id,'version',r.version_number));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'operational.mission.resources_recorded','mission',p_mission_id,jsonb_build_object('revision_id',r.id,'version',r.version_number));return jsonb_build_object('record',to_jsonb(r));end$$;

create function public.ftf_save_mission_actual_chemicals(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_expected_version integer,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare m public.missions%rowtype;current integer;r public.mission_operational_chemical_revisions%rowtype;a jsonb;begin select*into m from public.missions where organisation_id=p_organisation_id and id=p_mission_id and archived_at is null for update;if not found then return jsonb_build_object('not_found',true);end if;if not public.ftf_operational_location_allowed(p_organisation_id,p_actor_internal_user_id,m.operating_location_id)then return jsonb_build_object('location_forbidden',true);end if;select coalesce(max(version_number),0)into current from public.mission_operational_chemical_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id;if current<>p_expected_version then return jsonb_build_object('conflict',true,'current_version',current);end if;select evidence_manifest#>'{planning,chemicals}'into a from public.mission_authorisation_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id order by version_number desc limit 1;if a is null then return jsonb_build_object('not_authorised',true);end if;insert into public.mission_operational_chemical_revisions(organisation_id,operating_location_id,mission_id,version_number,changed_from_plan,actual_usage,planned_chemicals_snapshot,recorded_by_internal_user_id)values(p_organisation_id,m.operating_location_id,p_mission_id,current+1,coalesce((p_payload->>'changedFromPlan')::boolean,false),p_payload,a,p_actor_internal_user_id)returning*into r;insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'mission.actual_chemicals_saved','mission',p_mission_id,jsonb_build_object('revision_id',r.id,'version',r.version_number));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'operational.mission.chemicals_recorded','mission',p_mission_id,jsonb_build_object('revision_id',r.id,'version',r.version_number));return jsonb_build_object('record',to_jsonb(r));end$$;

create function public.ftf_save_mission_operational_events(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_expected_version integer,p_events jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare m public.missions%rowtype;current integer;i integer=0;e jsonb;ids jsonb='[]';r public.mission_operational_events%rowtype;begin select*into m from public.missions where organisation_id=p_organisation_id and id=p_mission_id and archived_at is null for update;if not found then return jsonb_build_object('not_found',true);end if;if not public.ftf_operational_location_allowed(p_organisation_id,p_actor_internal_user_id,m.operating_location_id)then return jsonb_build_object('location_forbidden',true);end if;select coalesce(max(batch_version),0)into current from public.mission_operational_events where organisation_id=p_organisation_id and mission_id=p_mission_id;if current<>p_expected_version then return jsonb_build_object('conflict',true,'current_version',current);end if;if jsonb_array_length(p_events)=0 then p_events=jsonb_build_array(jsonb_build_object('eventType','NO_OPERATIONAL_EVENTS','noEventsDeclaration',true));end if;for e in select value from jsonb_array_elements(p_events)loop insert into public.mission_operational_events(organisation_id,operating_location_id,mission_id,batch_version,event_index,event_type,event_details,occurred_at,no_events_declaration,recorded_by_internal_user_id)values(p_organisation_id,m.operating_location_id,p_mission_id,current+1,i,upper(e->>'eventType'),coalesce(e->'details','{}'),nullif(e->>'occurredAt','')::timestamptz,coalesce((e->>'noEventsDeclaration')::boolean,false),p_actor_internal_user_id)returning*into r;ids=ids||to_jsonb(r.id);i=i+1;end loop;insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'mission.operational_events_saved','mission',p_mission_id,jsonb_build_object('batch_version',current+1,'event_ids',ids));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'operational.mission.events_recorded','mission',p_mission_id,jsonb_build_object('batch_version',current+1,'event_ids',ids));return jsonb_build_object('records',(select jsonb_agg(to_jsonb(x))from public.mission_operational_events x where x.organisation_id=p_organisation_id and x.mission_id=p_mission_id and x.batch_version=current+1));end$$;

create function public.ftf_submit_mission_operational_evidence(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_expected_version integer,p_payload jsonb)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare m public.missions%rowtype;current integer;a public.mission_authorisation_revisions%rowtype;r public.mission_operational_resource_revisions%rowtype;c public.mission_operational_chemical_revisions%rowtype;o public.mission_operational_revisions%rowtype;imports uuid[];events uuid[];begin select*into m from public.missions where organisation_id=p_organisation_id and id=p_mission_id and archived_at is null for update;if not found then return jsonb_build_object('not_found',true);end if;if not public.ftf_operational_location_allowed(p_organisation_id,p_actor_internal_user_id,m.operating_location_id)then return jsonb_build_object('location_forbidden',true);end if;select*into a from public.mission_authorisation_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id order by version_number desc limit 1;select*into r from public.mission_operational_resource_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id order by version_number desc limit 1;select*into c from public.mission_operational_chemical_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id order by version_number desc limit 1;if a.id is null then return jsonb_build_object('not_authorised',true);end if;if r.id is null or c.id is null then return jsonb_build_object('evidence_incomplete',true);end if;select coalesce(array_agg(id order by version_number),'{}')into imports from public.mission_operational_imports where organisation_id=p_organisation_id and mission_id=p_mission_id and parse_status<>'REJECTED';select coalesce(array_agg(id order by batch_version,event_index),'{}')into events from public.mission_operational_events where organisation_id=p_organisation_id and mission_id=p_mission_id and batch_version=(select max(batch_version)from public.mission_operational_events where organisation_id=p_organisation_id and mission_id=p_mission_id);if cardinality(events)=0 then return jsonb_build_object('evidence_incomplete',true);end if;select coalesce(max(version_number),0)into current from public.mission_operational_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id;if current<>p_expected_version then return jsonb_build_object('conflict',true,'current_version',current);end if;insert into public.mission_operational_revisions(organisation_id,operating_location_id,mission_id,version_number,authorisation_revision_id,source_file_ids,resource_revision_id,chemical_revision_id,event_ids,review_snapshot,operator_notes,submitted_by_internal_user_id)values(p_organisation_id,m.operating_location_id,p_mission_id,current+1,a.id,imports,r.id,c.id,events,p_payload,trim(coalesce(p_payload->>'notes','')),p_actor_internal_user_id)returning*into o;insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'mission.operational_evidence_submitted','mission',p_mission_id,jsonb_build_object('revision_id',o.id,'version',o.version_number));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'operational.mission.evidence_submitted','mission',p_mission_id,jsonb_build_object('revision_id',o.id,'version',o.version_number));return jsonb_build_object('record',to_jsonb(o));end$$;

create function public.ftf_complete_mission(p_organisation_id uuid,p_actor_internal_user_id uuid,p_mission_id uuid,p_operational_revision_id uuid,p_expected_version integer,p_declaration text,p_override_reason text default null)returns jsonb language plpgsql security definer set search_path=public,pg_temp as $$declare m public.missions%rowtype;o public.mission_operational_revisions%rowtype;a public.mission_authorisation_revisions%rowtype;person public.personnel%rowtype;current integer;has_lines boolean;override boolean;c public.mission_completion_revisions%rowtype;snapshot jsonb;begin select*into m from public.missions where organisation_id=p_organisation_id and id=p_mission_id and archived_at is null for update;if not found then return jsonb_build_object('not_found',true);end if;if not public.ftf_operational_location_allowed(p_organisation_id,p_actor_internal_user_id,m.operating_location_id)then return jsonb_build_object('location_forbidden',true);end if;select*into o from public.mission_operational_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id and id=p_operational_revision_id;if not found then return jsonb_build_object('not_found',true);end if;select*into a from public.mission_authorisation_revisions where organisation_id=p_organisation_id and id=o.authorisation_revision_id;select exists(select 1 from public.mission_operational_imports i where i.organisation_id=p_organisation_id and i.id=any(o.source_file_ids)and i.evidence_type in('FINAL_KML','FLIGHT_LINES')and i.parse_status='PARSED')into has_lines;override=not has_lines;if override and length(trim(coalesce(p_override_reason,'')))=0 then return jsonb_build_object('flight_lines_required',true);end if;select*into person from public.personnel where organisation_id=p_organisation_id and internal_user_id=p_actor_internal_user_id and archived_at is null;if override and not found then return jsonb_build_object('personnel_required',true);end if;select coalesce(max(version_number),0)into current from public.mission_completion_revisions where organisation_id=p_organisation_id and mission_id=p_mission_id;if current<>p_expected_version then return jsonb_build_object('conflict',true,'current_version',current);end if;snapshot=jsonb_build_object('schemaVersion',1,'planningAndPreflightAuthorisation',to_jsonb(a),'operationalEvidence',to_jsonb(o),'completedAt',now(),'flightLinesEvidenceAvailable',has_lines,'historicalFlag',case when override then'FLIGHT_LINES_OVERRIDE'else null end);insert into public.mission_completion_revisions(organisation_id,operating_location_id,mission_id,version_number,authorisation_revision_id,operational_revision_id,completion_snapshot,declaration,flight_lines_override,override_reason,override_personnel_id,completed_by_internal_user_id)values(p_organisation_id,m.operating_location_id,p_mission_id,current+1,a.id,o.id,snapshot,trim(p_declaration),override,nullif(trim(coalesce(p_override_reason,'')),''),case when override then person.id else null end,p_actor_internal_user_id)returning*into c;insert into public.audit_events(organisation_id,actor_internal_user_id,event_type,entity_type,entity_id,event_payload)values(p_organisation_id,p_actor_internal_user_id,'mission.completed','mission',p_mission_id,jsonb_build_object('completion_revision_id',c.id,'version',c.version_number,'flight_lines_override',override));insert into public.transactional_outbox(organisation_id,topic,aggregate_type,aggregate_id,payload)values(p_organisation_id,'completion.mission.completed','mission',p_mission_id,jsonb_build_object('completion_revision_id',c.id,'version',c.version_number,'flight_lines_override',override));return jsonb_build_object('record',to_jsonb(c));end$$;

